#include <stdio.h>
int main(void) {
    int n = 4;
    int values[4] = {3, -2, 8, 0};
    int minimum = values[0];
    int maximum = values[0];
    for (int i = 1; i < n; i = i + 1) {
        if (values[i] < minimum) {
            minimum = values[i];
        }
        if (values[i] > maximum) {
            maximum = values[i];
        }
    }
    printf("%d %d\n", minimum, maximum);
    return 0;
}
